def longest_increasing_subarray(nums):
    def helper(start, end, max_len):
        if end == len(nums):
            return max_len
        if nums[end] > nums[end - 1]:
            return helper(start, end + 1, max_len + 1)
        else:
            return max(max_len, helper(end, end + 1, 1))

    return helper(0, 1, 1)
